from datetime import datetime
import os, re

# Login to file_system
access_token = apis.file_system.login(username='spencer.powell@gmail.com', password='P}OX+bi')['access_token']

now_year = datetime.now().year
print('year', now_year)

base_dir_rel = '~/photographs/vacations'
base_abs = '/home/spencer/photographs/vacations'  # derived from earlier paths

# Get top-level files
files = apis.file_system.show_directory(directory_path=base_dir_rel+'/', access_token=access_token, entry_type='files', recursive=False)
print('top files', len(files))

# Categorize by created month (this year only: March=Rome, April=Santorini; else Berlin)
def parse_ym(created_at_str):
    m = re.match(r'^(\d{4})-(\d{2})-', created_at_str or '')
    if not m:
        return None
    return int(m.group(1)), int(m.group(2))

categories = {'Rome': [], 'Santorini': [], 'Berlin': []}
file_map = {}
for fp in files:
    meta = apis.file_system.show_file(file_path=fp, access_token=access_token)
    created_at = meta.get('created_at')
    ym = parse_ym(created_at)
    if ym and ym[0] == now_year and ym[1] == 3:
        cat = 'Rome'
    elif ym and ym[0] == now_year and ym[1] == 4:
        cat = 'Santorini'
    else:
        cat = 'Berlin'
    categories[cat].append(fp)
    file_map[fp] = {'created_at': created_at, 'cat': cat}

print({k: len(v) for k,v in categories.items()})

# Create subdirectories if missing
for cat in ['Rome','Santorini','Berlin']:
    dest_dir = f"{base_dir_rel}/{cat}"
    exists = apis.file_system.directory_exists(directory_path=dest_dir, access_token=access_token)['exists']
    print('dir', dest_dir, 'exists', exists)
    if not exists:
        apis.file_system.create_directory(directory_path=dest_dir, access_token=access_token, recursive=True, allow_if_exists=True)
        print('created', dest_dir)

# Move files
moved = {'Rome':0,'Santorini':0,'Berlin':0}
failures=[]

for cat, fps in categories.items():
    dest_dir_abs = f"{base_abs}/{cat}"
    for src in fps:
        filename = src.split('/')[-1]
        dest = f"{dest_dir_abs}/{filename}"
        # Move
        res = apis.file_system.move_file(source_file_path=src, destination_file_path=dest, access_token=access_token, overwrite=False, retain_dates=True)
        moved[cat]+=1
        if 'destination_file_path' in res:
            pass
        else:
            # if failure shape
            failures.append((src,dest,res))

print('moved counts', moved)
print('failures', len(failures))
if failures:
    print(failures[:2])

